from sqlalchemy.orm import Sessionfrom . import models, authdef get_user_by_username(db: Session, username: str):    return db.query(models.User).filter(models.User.username == username).first()def create_user(db: Session, username: str, password: str, is_admin: bool = False, credits: int = 0):    hashed = auth.get_password_hash(password)    user = models.User(username=username, hashed_password=hashed, is_admin=is_admin, credits=credits)    db.add(user)    db.commit()    db.refresh(user)    return userdef add_credits(db: Session, user_id: int, amount: int):    user = db.query(models.User).filter(models.User.id == user_id).first()    if not user:        return None    user.credits += amount    db.commit()    db.refresh(user)    return userdef consume_credits(db: Session, user_id: int, amount: int) -> bool:    user = db.query(models.User).filter(models.User.id == user_id).first()    if not user or user.credits < amount:        return False    user.credits -= amount    db.commit()    return Truedef log_search(db: Session, user_id: int, query_type: str, query_value: str, credits_used: int, summary: str, raw_result: dict, ip: str = None):    from . import models    entry = models.SearchLog(        user_id=user_id,        query_type=query_type,        query_value=query_value,        credits_used=credits_used,        result_summary=summary,        raw_result=raw_result,        ip_address=ip    )    db.add(entry)    db.commit()    db.refresh(entry)    return entry